/**
 * @name Path traversal vulnerability
 * @description Path traversal via file operations without proper validation
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for file operations that could be vulnerable to path traversal
    exists(DataFlow::CallCfgNode call |
      // os.path operations
      call = API::moduleImport("os").getMember("path").getMember("join").getACall() and
      sink = call.getArg(1)
    ) or
    exists(DataFlow::CallCfgNode call |
      // open() function calls
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      // file operations
      call = API::moduleImport("os").getMember(["open", "remove", "unlink", "rename"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability: user input may control file path $@.", source.getNode(), "user input"

/**
 * @name Command injection vulnerability
 * @description Using user input in command execution can lead to arbitrary command execution
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for os.system, subprocess.call, etc.
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("os").getMember("system").getACall() or
        call = API::moduleImport("subprocess").getMember(["call", "run", "Popen"]).getACall() or
        call = API::moduleImport("os").getMember("popen").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection: user input may control command execution $@.", source.getNode(), "user input"
